// Sort mapping keys by length descending to match longest sequences (conjuncts, syllables) first
const sortedKeys = Object.keys(unicodeToAakritiMap).sort((a, b) => b.length - a.length);

// Helper to escape regex special characters
function escapeRegExp(string: string): string {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Compile a single-pass regex pattern for all keys
const pattern = sortedKeys.map(escapeRegExp).join('|');
const conversionRegex = new RegExp(pattern, 'g');

export function unicodeToAakriti(text: string): string {
  if (!text) return '';
  const str = String(text);
  const converted = str.replace(conversionRegex, (match) => unicodeToAakritiMap[match]);
  // Prevent line breaks inside mapped ASCII representations by inserting Word Joiners (U+2060)
  // around breakable characters like pipe '|', slash '/', and backslash '\'
  return converted.replace(/([|/\\])/g, '\u2060$1\u2060');
}

/**
 * Helper to get the correct font style object based on active language.
 */
export function getNepaliFontStyle(isNepali: boolean, isBold: boolean = false) {
  if (!isNepali) return {};
  return {
    fontFamily: isBold ? 'AakritiBold' : 'Aakriti',
  };
}

/**
 * Helper to convert text for rendering in Aakriti font when Nepali is enabled.
 */
export function npText(text: string, isNepali: boolean): string {
  if (!isNepali) return text;
  return unicodeToAakriti(text);
}
